-- Schéma + données initiales pour l'appli Suivi Chantiers (SYNERGIE BTP)
-- À exécuter une fois dans l'éditeur SQL de Supabase (Project > SQL Editor > New query)

create table if not exists kv_store (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

-- RLS activé : personne ne peut lire/écrire directement depuis le navigateur.
-- Seule la route API serveur (qui utilise la clé service_role, laquelle
-- contourne RLS) peut accéder à cette table.
alter table kv_store enable row level security;

